const seen = new Map<number, string | null>();
let page = 1;
let rawCount = 0;
let noLogin = 0;
let prCount = 0;
while (page <= 200) {
  const res: any = await tools.list_issues({ repo: "acme/web", state: "all", page });
  const items: any[] = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? res?.data ?? []);
  if (!items.length) break;
  for (const it of items) {
    rawCount++;
    if (it.pull_request || it.is_pull_request) { prCount++; continue; }
    const login = it.user?.login ?? (typeof it.user === "string" ? it.user : null);
    if (typeof login !== "string") noLogin++;
    if (!seen.has(it.number)) seen.set(it.number, typeof login === "string" ? login : null);
  }
  page++;
}
const counts: Record<string, number> = {};
for (const login of seen.values()) {
  if (login) counts[login] = (counts[login] ?? 0) + 1;
}
const ranked = Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
return { lastPage: page - 1, rawCount, uniqueIssues: seen.size, noLogin, prCount, top: ranked.slice(0, 5) };
